(function(){
  'use strict';
  const engine=AuditConversation.createEngine(), $=id=>document.getElementById(id);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const button=(label,action,extra='',primary=false)=>'<button '+(primary?'class="primary" ':'')+'data-action="'+action+'" '+extra+'>'+esc(label)+'</button>';
  const tag=(text,warn=false)=>'<span class="tag '+(warn?'warn':'')+'">'+esc(text)+'</span>';
  const names={'roles':'角色与用途','access':'允许访问','required':'必要访问','exception':'业务例外'};
  const assets=i=>i?.targets?.map(a=>a.name+'（'+a.region+' / '+a.type+' / '+a.id+'）').join('、')||'待明确';
  let scrollOnRender=true;
  function card(c,s){if(!c)return '';const i=c.plan?.scope||s.intent,p=c.plan||s.plan,t=engine.visibleTask(c.taskId);let head='',body='',actions='';
    if(c.type==='plan'){
      const valid=s.plan&&s.plan.revision===c.revision&&!s.plan.accepted;head='本次审计计划';body='<dl><dt>审计对象</dt><dd>'+esc(i?.targets?.length>3?i.targets.length+' 台 ECS · '+i.query+' · '+Array.from(new Set(i.targets.map(a=>a.region))).join('／'):assets(i))+'</dd><dt>边界</dt><dd>'+esc(i?.boundary==='NAT'?'NAT 边界 ACL，不含完整地址转换审计':i?.boundary==='出向'?'互联网边界 · 有限出向':'互联网边界 · 入向')+'</dd><dt>资料策略</dt><dd>'+esc(p?.dataLabel||'以当前计划为准')+'</dd><dt>模型模式</dt><dd>'+esc(p?.mode==='rules-only'?'只做规则检查':'规则与模型补充（人工模拟）')+'</dd><dt>业务确认</dt><dd>v'+(p?.profile||s.profile).version+'；角色'+((p?.profile||s.profile).roles?'已确认':'未知')+'，允许访问'+((p?.profile||s.profile).access?'已确认':'未知')+'</dd><dt>执行效果</dt><dd>'+esc(p?.mode==='rules-only'?'只读准备有限资料并运行规则，不调用模型补充。':'只读准备有限资料，运行规则并补充解释。')+'此页面均为自动推进的人工模拟。</dd></dl>';
      actions=valid?button('确认计划，开始模拟','start','',true)+button('补充业务资料','prepare-business')+(p?.mode==='rules-only'?button('规则与模型补充','rules-agent'):button('只做规则检查','rules-only')):tag('此计划已接受或已被后续修改替代');
    } else if(c.type==='candidates'){head='请选择规范对象';body='<div class="choice-list">'+s.candidates.map(a=>'<button class="choice" data-action="choose" data-id="'+esc(a.id)+'"><span><strong>'+esc(a.name)+' · '+esc(a.region)+'</strong><small>'+esc(a.type)+' / '+esc(a.id)+'</small><small>目录：2026-10-29 09:00（人工）</small></span><span>选择</span></button>').join('')+'</div>';
    } else if(c.type==='discovery'){head='准备资源目录';body='<dl><dt>地域</dt><dd>'+esc(i?.region||'待明确')+'</dd><dt>筛选</dt><dd>'+esc(i?.query||'待明确')+' / '+esc(i?.type||'支持的资源类型')+'</dd><dt>效果</dt><dd>有限只读发现后继续本次意图；对象歧义时仍需选择。不会要求逐台预配资产。</dd></dl>';actions=button('确认有限发现（模拟）','discover','',true)+button('改用人工资料','offline');
    } else if(c.type==='catalogue-partial'){head='已见对象与目录缺口';body='<p>已见 '+s.candidates.length+' 个匹配对象；未穷尽的目录不证明其他对象不存在。</p>'+s.candidates.map(a=>'<div class="object-row">'+esc(a.name)+' / '+esc(a.id)+'</div>').join('');actions=button('仅审已见子集','seen-only','',true)+button('继续有限目录刷新','discover');
    } else if(c.type==='region'){head='选择发现地域';actions=button('杭州','phrase','data-text="杭州"')+button('北京','phrase','data-text="北京"');
    } else if(c.type==='batch'){head='范围与批次';body='<p>完整匹配 '+c.count+' 个对象。逐个对象可在右侧查看；也可输入“支付业务群”限定为 20 台。</p>';actions=button('选择完整范围分批模拟','batch','',true)+button('收窄为支付业务群','phrase','data-text="检查杭州支付业务群的入向策略"');
    } else if(c.type==='business'){head='分项确认业务资料';body='<p>候选线索尚未批准。用途确认不等于访问授权；每一项都可保留未知。</p>';actions=button('角色与用途','edit-business','data-part="roles"')+button('允许访问','edit-business','data-part="access"')+button('必要访问','edit-business','data-part="required"')+button('业务例外','edit-business','data-part="exception"')+button('拒绝候选','reject-candidate')+button('保留未知，先查基线','unknown');
    } else if(c.type==='business-preview'){head='确认预览 · '+names[c.part];const pending=s.pending?.id===c.pending?.id&&s.pending.base===s.profile.version?s.pending:null;body=pending?'<dl><dt>对象</dt><dd>'+esc(i?.targets.length+' 个对象：'+assets(i))+'</dd><dt>本次项目</dt><dd>'+esc(names[c.part])+'</dd><dt>内容</dt><dd>'+esc(c.part==='roles'?pending.data.roles+'；服务绑定：'+(pending.data.services||'端口未声明'):c.part==='exception'?pending.data.exceptionObject+' / '+pending.data.exceptionCheck+' / '+pending.data.exceptionReason+' / '+pending.data.exceptionSource+' / 至 '+pending.data.exceptionUntil:c.part==='access'?(s.profile.services?.find(v=>v.id===pending.data.serviceId)?.name||'资源级')+'：'+pending.data.sources+' / '+pending.data.ports+'；集合'+(pending.data.complete?'完整':'未声明完整'):[s.profile.services?.find(v=>v.id===pending.data.serviceId)?.name||'资源级',pending.data.requiredTargets,pending.data.requiredPorts,pending.data.required].filter(Boolean).join(' / '))+'</dd><dt>版本变化</dt><dd>v'+pending.base+' → v'+(pending.base+1)+'；仅更新所列项目</dd></dl>':'<p>预览已完成或失效。旧任务仍绑定原版本。</p>';actions=pending?button('确认这项资料','confirm-business','data-pending-id="'+pending.id+'"',true)+button('继续编辑','edit-business','data-part="'+c.part+'"'):tag('已处理');
    } else if(c.type==='conflict'){head='用途冲突待复核';body='<p>原确认：数据库；新线索：Web 服务。请选择保留原确认或编辑后重新确认。</p>';actions=button('保留原用途','keep-profile')+button('修订用途','edit-business','data-part="roles"');
    } else if(c.type==='connection'){head='继续完成审计';body='<p>连接条件与资源是否存在分开。凭据由管理员在服务端配置，不在聊天填写。</p>';actions=button('使用人工资料继续','offline','',true);
    } else if(c.type==='result'){head=t?.stage||'查看任务结果';body='<p>查看固定输入、逐项证据和未完成项。审阅记录与规则判定分开。</p>';actions=button('查看结果与证据','panel','data-panel="results" data-task-id="'+c.taskId+'"',true)+button('查看固定报告','report','data-task-id="'+c.taskId+'"')+button('人工改后复审','recheck','data-task-id="'+c.taskId+'"');
    } else if(c.type==='task'){head='计划已受理';body='<p>无需操作内部执行阶段。可以继续询问进展，或明确取消。</p>';actions=button('查看当前进度','phrase','data-text="任务到哪一步了？"')+button('取消任务','cancel','data-task-id="'+c.taskId+'"');
    } else if(c.type==='explanation'){head='解释固定历史结果';body='<p>沿用原对象、边界与证据时点。询问当前风险将另行核对资料策略。</p>';actions=button('查看证据','panel','data-panel="results" data-task-id="'+c.taskId+'"');
    } else if(c.type==='ack-unknown'){head='受理答复未知';body='<p>先恢复同一提交的观察，再决定是否重试。不会因点击重试重复执行。</p>';actions=button('查询原提交并恢复观察','reconnect','',true);
    } else if(c.type==='save-failed'){head='尚未保存';body='<p>草稿仍在，未生成新的确认版本。</p>';actions=button('重试保存这项资料','confirm-business','',true);
    } else if(c.type==='secret'){head='凭据不进入对话';body='<p>受控配置入口由服务端管理。这里不提供密钥表单。</p>';
    } else if(c.type==='defer'){head='暂缓理由';actions=button('填写暂缓理由','defer');
    } else return '';
    return '<div class="card"><div class="card-head"><h3>'+esc(head)+'</h3>'+tag('人工模拟')+'</div>'+(body?'<div class="card-body">'+body+'</div>':'')+(actions?'<div class="actions">'+actions+'</div>':'')+'</div>';
  }
  function context(s,t){const i=t?.scope||s.intent,profile=t?.profile||s.profile;if(!i?.targets?.length){const cs=s.candidates;return '<div class="support-empty"><svg width="45" height="48" viewBox="0 0 45 48" fill="none" aria-hidden="true"><rect x="7" y="5" width="31" height="38" rx="7" stroke="#9bb7ab"/><path d="M15 16h15M15 24h15M15 32h9" stroke="#9bb7ab"/></svg><h3>'+(cs?.length?'等待选择对象':'从你的目标开始')+'</h3><p>'+(cs?.length?'候选尚未绑定审计。补充地域或选择 ID 后继续。':'目标明确后，在这里查看对象、资料来源与业务确认。')+'</p></div>'+(cs?.length?'<div class="support-block">'+cs.map(a=>'<div class="object-row">'+esc(a.name)+' · '+esc(a.region)+'<small>'+esc(a.id)+'</small></div>').join('')+'</div>':'');}
    const scopeMatches=!t||JSON.stringify(t.scope.targets.map(a=>a.id))===JSON.stringify(s.intent?.targets?.map(a=>a.id))&&t.scope.boundary===s.intent?.boundary;const info=t?.input;return '<section class="support-block"><h3>'+(t?'固定任务对象 ':'本次计划对象 ')+tag(i.targets.length+' 个')+'</h3><p>'+esc(i.boundary)+' · '+esc(Array.from(new Set(i.targets.map(a=>a.region))).join('／'))+' · 演示账号</p><div class="object-list">'+i.targets.map(a=>'<div class="object-row">'+esc(a.name)+'<small>'+esc(a.region)+' / '+esc(a.type)+' / '+esc(a.id)+'</small></div>').join('')+'</div></section><section class="support-block"><h3>资料与来源</h3><p>'+esc(info?info.source:'人工资源目录，不是云观测')+'</p><p class="meta">时点：'+esc(info?info.time:'2026-10-29 09:00（人工时点）')+'<br>状态：'+esc(info?info.complete?'完整人工样例':'资料部分缺失':'目录可用于本地解析，审计资料尚未封存')+'</p>'+(info?tag(info.version):'')+'<details><summary class="inline-muted">展开自动取得的线索</summary><ul class="fact-list">'+i.targets.slice(0,3).map(a=>'<li>'+esc(a.clue)+'</li>').join('')+'</ul><p>标签、端口和共享组仅支持候选，不能证明服务监听、实际可达或业务授权。</p></details></section><section class="support-block"><h3>'+(t?'任务绑定业务确认':'当前业务确认')+' v'+profile.version+'</h3><p>角色：'+esc(profile.roles||'未知')+'<br>允许访问：'+esc(profile.accessEntries?.length?profile.accessEntries.length+' 个服务分项':profile.access?profile.access.sources+' / '+profile.access.ports:'未声明')+'<br>必要访问：'+esc(profile.required||'未声明')+'</p>'+((profile.accessEntries?.length?'<ul class="fact-list">'+profile.accessEntries.map(v=>'<li>'+esc(v.serviceName)+'：'+esc(v.sources)+' / '+esc(v.ports)+'；v'+v.version+'</li>').join('')+'</ul>':'')+(profile.requiredEntries?.length?'<ul class="fact-list">'+profile.requiredEntries.map(v=>'<li>必要：'+esc(v.service)+' / '+esc(v.targets)+' / '+esc(v.ports)+'；v'+v.version+'</li>').join('')+'</ul>':'')+(profile.services?.length?'<ul class="fact-list">'+profile.services.map(x=>'<li>'+esc(x.name)+' / '+esc(x.ports)+' / '+esc(x.assets.join('、'))+'</li>').join('')+'</ul>':''))+((profile.archivedAccessEntries?.length||profile.archivedRequiredEntries?.length)?'<p class="meta">另有 '+((profile.archivedAccessEntries?.length||0)+(profile.archivedRequiredEntries?.length||0))+' 条原服务历史资料，已退出当前判据。</p>':'')+(scopeMatches?'<div class="actions">'+button('修订当前资料，保留原报告','prepare-business')+'</div>':'<p class="report-banner">这里展示固定任务。当前对话另有目标：'+esc(assets(s.intent))+'。请在聊天中确认该目标的业务资料。</p>')+'<p class="meta">每项分别确认。旧结果保持原版本。</p></section>'+(s.drafts?'<section class="support-block"><h3>保留的业务草稿</h3>'+Object.keys(s.drafts).map(key=>button('恢复 '+(s.draftScopes[key]?.targets[0]?.name||'原对象')+' '+(s.draftScopes[key]?.boundary||''),'restore-draft','data-key="'+esc(key)+'"')).join('')+'</section>':'')+(t?'<section class="support-block"><h3>执行记录</h3>'+timeline(t)+'</section>':'');
  }
  function timeline(t){return '<ol class="timeline">'+t.events.map(e=>'<li>'+esc(e.stage||'任务记录')+(e.note?'<p>'+esc(e.note)+'</p>':'')+'<small>模拟经过 '+e.at+' 秒</small></li>').join('')+'</ol>'+(t.mode==='disconnected'?'<p class="report-banner">观察已断开。任务可能继续，页面仅展示已收到的记录。</p>':'');}
  function results(s,t){if(!t?.findings.length)return '<div class="support-empty"><h3>结果尚未就绪</h3><p>规则样例产生并送达后会先出现在这里，无需等待模型补充。</p></div>';
    const st=engine.getState(),index=Math.min(st.selectedFinding,t.findings.length-1),f=t.findings[index],raw=st.tasks.find(x=>x.id===t.id),review=raw.reviews?.[f.id];return '<section class="support-block"><h3>'+t.findings.length+' 条结果 '+tag(t.status==='partial'?'部分完成':t.status==='running'?'持续接收':'固定结果',t.status==='partial')+'</h3><p>规则事实、业务推导、待确认及信息不足分别保留。</p></section><div class="finding-list">'+t.findings.map((x,j)=>'<button class="finding-item" data-action="finding" data-index="'+j+'" aria-current="'+(j===index)+'">'+tag(x.kind,x.kind!=='规则事实')+'<strong>'+esc(x.title)+'</strong></button>').join('')+'</div><article class="finding-detail"><h3>'+esc(f.title)+'</h3><span class="evidence-label">结论与范围</span><p>'+esc(f.detail)+'</p><span class="evidence-label">可定位证据</span><p>'+esc(f.evidence)+'</p><span class="evidence-label">建议成立条件</span><p>'+esc(f.condition)+'</p><span class="evidence-label">可能影响</span><p>'+esc(f.impact)+'</p>'+(review?'<div class="review-state">审阅：'+esc(review.kind)+(review.reason?'；'+esc(review.reason):'')+'<br>未改变原始判定，未执行云上修改。</div>':'')+'<div class="actions">'+button('加入本地待办','review','data-kind="本地待办"',true)+button('暂缓并记录理由','defer')+'</div><div class="actions">'+button('追问这项依据','phrase','data-text="解释这项发现的依据与影响"')+button('补充缺少资料','prepare-business')+'</div></article>';
  }
  function report(){const r=engine.report();if(!r)return '<div class="support-empty"><h3>还没有固定报告</h3><p>任务结束后可查看完整或部分报告。进行中的任务请查看结果。</p></div>';return '<section class="support-block"><h3>审计报告 '+tag(r.status==='partial'?'部分完成':r.status==='cancelled'?'已取消':r.status==='interrupted'?'已中断':r.status==='failed'?'未完成':'已完成',r.status!=='completed')+'</h3><div class="report-banner">人工构造资料与固定结果。不是正式审计报告，不代表真实云或模型验证。</div><p>对象：'+esc(r.scope.targets.length+' 个 / '+r.scope.targets.map(x=>x.name).slice(0,2).join('、'))+'<br>边界：'+esc(r.scope.boundary)+'<br>资料：'+esc(r.input.version)+'<br>时点：'+esc(r.input.time)+'<br>业务确认：v'+r.profile.version+'</p><div class="actions">'+button('导出 Markdown','export','',true)+button('导出 JSON','export-json')+button('准备改后复审','recheck')+'</div></section>'+(r.comparison?'<section class="support-block"><h3>'+esc(r.comparison.kind==='comparable'?'与原报告比较':'不可直接比较')+'</h3><p>'+esc(r.comparison.text)+'</p>'+r.comparison.items.map(x=>'<div class="history-item">'+tag(x.kind)+'<p>对象：'+esc(x.object)+'</p><p>之前：'+esc(x.before)+'</p><p>之后：'+esc(x.after)+'</p><p>'+esc(x.reason)+'</p></div>').join('')+'</section>':'')+'<section class="support-block"><h3>结论与审阅</h3>'+r.findings.map(f=>'<div class="history-item">'+tag(f.kind)+'<b>'+esc(f.title)+'</b><p>'+esc(r.reviews[f.id]?.kind||'待审阅')+'</p></div>').join('')+'</section><section class="support-block"><h3>保证边界</h3><p>仅覆盖固定对象、边界、受支持语义和证据时点。未知不等于缺失；配置允许不等于实际可达。待办不代表整改。</p></section>';}
  function history(s){const ts=engine.getState().tasks.filter(x=>x.session===s.id);return '<section class="support-block"><h3>本会话历史</h3><p>页面内存中的演示历史。刷新会清空，未实现正式持久化与重启恢复。</p></section>'+(ts.length?ts.map(t=>'<article class="history-item"><b>'+esc(t.id)+' · '+esc(t.scope.boundary)+'</b><p>'+esc(t.scope.targets.length+' 个对象 / 业务确认 v'+t.profile.version)+'</p><p>'+esc(t.received.at(-1)?.stage||'已受理')+'</p>'+(!['running','queued'].includes(t.status)?button('打开这份报告','open-report','data-id="'+t.id+'"'):'')+'</article>').join(''):'<div class="support-empty"><p>还没有任务。表达目标后从同一对话继续。</p></div>');}
  function render(){const st=engine.getState(),s=engine.getSession(),t=engine.visibleTask(),scroll=$('conversation'),wasBottom=scroll.scrollHeight-scroll.scrollTop-scroll.clientHeight<80;
    $('sessionTitle').textContent=s.title;$('slotCount').textContent=st.tasks.filter(x=>x.status==='running').length+' / 3 执行中';
    $('sessionList').innerHTML=st.sessions.map(x=>'<button class="session-item" data-action="select-session" data-id="'+x.id+'" aria-current="'+(x.id===s.id)+'">'+esc(x.title)+'<span>'+esc(x.taskIds.length?st.tasks.find(y=>y.id===x.taskIds.at(-1))?.received.at(-1)?.stage||'已受理':'等待你的目标')+'</span></button>').join('');
    $('welcome').innerHTML=s.messages.length<=1?'<div class="welcome"><div class="welcome-symbol" aria-hidden="true">◇</div><h2>先说说，你想检查什么？</h2><p>从一台资源、一组业务或一份历史结果开始。对象明确后，我会把审计范围和下一步列给你。</p></div>':'';
    $('messages').innerHTML=s.messages.map(m=>'<article class="message '+m.role+'"><div class="sender">'+(m.role==='user'?'你':'审计助手')+'</div>'+(m.role==='user'?'<p class="bubble">'+esc(m.text)+'</p>':'<div class="text">'+esc(m.text)+'</div>'+card(m.card,s))+'</article>').join('');
    const phrases=!s.intent?['检查杭州 web-prod 的入向策略','审计支付业务群的 20 台 ECS','检查 nat-prod 的 NAT 边界']:t&&!['running','queued'].includes(t.status)?['解释这项发现的依据','我已在云端改好，重新采集复审','查看任务状态']:s.plan?['不知道管理白名单，先查基线','检查出向策略','查看任务状态']:['杭州','北京','检查杭州 db-prod'];
    $('suggestions').innerHTML=phrases.map(x=>'<button data-action="fill" data-text="'+esc(x)+'">'+esc(x)+'</button>').join('');
    $('taskStrip').innerHTML=t&&['running','queued'].includes(t.status)?'<div><span class="progress-pulse"></span><b>'+esc(t.stage)+'</b> <small>'+esc(t.mode==='disconnected'?'观察已断开':'自动模拟推进')+'</small></div>'+button('取消任务','cancel'):'';
    document.querySelectorAll('[role=tab]').forEach(x=>{x.setAttribute('aria-selected',String(x.dataset.panel===st.panel));x.tabIndex=x.dataset.panel===st.panel?0:-1;});
    $('supportBody').innerHTML=st.panel==='context'?context(s,t):st.panel==='results'?results(s,t):st.panel==='report'?report():history(s);
    $('notice').textContent=st.notice;if(wasBottom||scrollOnRender)scroll.scrollTop=scroll.scrollHeight;scrollOnRender=false;
  }
  function openBusiness(part){const s=engine.getSession();if(!s.intent?.targets?.length)return;const d=s.draft,serviceOptions='<option value="asset-default">资源级（未指定服务）</option>'+(s.profile.services||[]).map(v=>'<option value="'+esc(v.id)+'">'+esc(v.name)+'</option>').join('');$('businessPart').value=part;$('businessTitle').textContent='编辑'+names[part];$('businessDescription').textContent=part==='roles'?'候选来自标签和关联组，只确认实际用途。允许访问与必要访问不随用途自动确认。':part==='access'?(s.intent.boundary==='出向'?'为发起资产确认外部目标和协议端口。入向管理来源不能替代出向目标。':'确认允许的来源、协议端口和集合完整性。未填写表示未知。'):'必要性必须由业务确认；已放行配置和历史流量不能代替业务要求。';
    $('businessFields').innerHTML=part==='roles'?'<label for="roleInput">实际角色或服务</label><input id="roleInput" name="roles" value="'+esc(d.roles||s.profile.roles||'')+'" placeholder="例如：Web 服务、数据库，或多角色"><p class="inline-muted">候选：'+esc(d.roles||'信息不足，保持未知')+'</p><label for="servicesInput">服务绑定，每行服务名 | 协议端口</label><textarea id="servicesInput" name="services" rows="3" placeholder="例如：门户HTTPS | TCP443；端口未知可留空">'+esc(d.services||'')+'</textarea>':part==='access'?'<label for="accessService">适用服务</label><select id="accessService" name="serviceId">'+serviceOptions+'</select><label for="sourceInput">'+(s.intent.boundary==='出向'?'允许外部目标':'允许访问来源')+'</label><input id="sourceInput" name="sources" value="'+esc(d.sources||'')+'" placeholder="由业务负责人声明的地址或网段"><label for="portsInput">协议与端口</label><input id="portsInput" name="ports" value="'+esc(d.ports||'')+'" placeholder="例如：TCP 443"><label class="check"><input name="complete" type="checkbox" '+(d.complete?'checked':'')+'> 我确认这份允许集合完整</label><p class="inline-muted">如确实禁止全部，请明确填写“禁止全部”并核对适用范围。</p>':part==='exception'?'<label for="exceptionObject">适用对象</label><input id="exceptionObject" name="exceptionObject" value="'+esc(s.intent.targets.map(a=>a.id).join('、'))+'"><label for="exceptionCheck">适用检查</label><input id="exceptionCheck" name="exceptionCheck" placeholder="例如：管理入口限制基线"><label for="exceptionReason">例外理由</label><input id="exceptionReason" name="exceptionReason"><label for="exceptionSource">授权来源</label><input id="exceptionSource" name="exceptionSource" placeholder="例如：负责人确认单 DEMO-01"><label for="exceptionUntil">到期日</label><input type="date" id="exceptionUntil" name="exceptionUntil"><p class="inline-muted">只适用所列对象和检查；缺项或已过期不生效。</p>':'<label for="requiredInput">必要访问与用途</label><label for="requiredService">适用服务</label><select id="requiredService" name="serviceId">'+serviceOptions+'</select><label for="requiredTargets">必要调用来源或目标</label><input id="requiredTargets" name="requiredTargets"><label for="requiredPorts">必要协议端口</label><input id="requiredPorts" name="requiredPorts" placeholder="TCP443"><label for="requiredInput">必要性说明</label><textarea id="requiredInput" name="required" rows="3" placeholder="例如：应用服务必须访问 10.0.2.0/24 TCP 3306">'+esc(d.required||'')+'</textarea>';
    $('businessDialog').showModal();}
  function download(json=false){const r=engine.report();if(!r)return;const data=engine.exportReport(json?'json':'markdown');const url=URL.createObjectURL(new Blob([data],{type:json?'application/json;charset=utf-8':'text/markdown;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='人工演示审计报告-'+r.id+(json?'.json':'.md');link.click();setTimeout(()=>URL.revokeObjectURL(url),0);}
  function submit(){const text=$('messageInput').value.trim();if(!text)return;$('messageInput').value='';engine.send(text);scrollOnRender=true;render();}
  $('importButton').addEventListener('click',()=>{$('importText').value=JSON.stringify({schema_version:1,source:'公开人工演示',collected_at:'2026-10-29 09:00',complete:true,resources:[{id:'i-import-01',name:'import-web',region:'杭州',type:'ECS'}]},null,2);$('importError').textContent='';$('importDialog').showModal();});$('importForm').addEventListener('submit',e=>{e.preventDefault();const imported=engine.act('import',{text:$('importText').value});if(imported)$('importDialog').close();else $('importError').textContent=engine.getSession().messages.at(-1).text;scrollOnRender=true;render();});
  $('scenario').innerHTML=Object.entries(AuditConversation.scenarioNames).map(([key,label])=>'<option value="'+key+'">'+esc(label)+'</option>').join('');
  $('scenario').addEventListener('change',e=>{engine.act('scenario',{value:e.target.value});render();});
  $('composer').addEventListener('submit',e=>{e.preventDefault();submit();});$('messageInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();submit();}});
  $('newSession').addEventListener('click',()=>{engine.act('new-session');scrollOnRender=true;render();});
  $('contextToggle').addEventListener('click',()=>{const hidden=$('support').classList.toggle('collapsed');$('contextToggle').setAttribute('aria-expanded',String(!hidden));});
  if(innerWidth<951){$('support').classList.add('collapsed');$('contextToggle').setAttribute('aria-expanded','false');}
  document.addEventListener('click',e=>{const close=e.target.closest('[data-close-dialog]');if(close){close.closest('dialog').close();return;}const x=e.target.closest('[data-action],[data-panel]');if(!x)return;const a=x.dataset.action||'panel';if(a==='fill'){$('messageInput').value=x.dataset.text;$('messageInput').focus();return;}if(a==='phrase'){engine.send(x.dataset.text);scrollOnRender=true;}else if(a==='edit-business'){openBusiness(x.dataset.part);return;}else if(a==='defer'){$('deferDialog').showModal();return;}else if(a==='export'||a==='export-json'){download(a==='export-json');return;}else engine.act(a,{id:x.dataset.id,index:x.dataset.index,panel:x.dataset.panel,kind:x.dataset.kind,pendingId:x.dataset.pendingId,taskId:x.dataset.taskId,key:x.dataset.key});
    if(a==='unknown'&&$('businessDialog').open)$('businessDialog').close();if(['panel','finding','report','open-report'].includes(a)){$('support').classList.remove('collapsed');$('contextToggle').setAttribute('aria-expanded','true');}if(!['panel','finding','report','open-report'].includes(a))scrollOnRender=true;render();});
  $('businessFields').addEventListener('change',event=>{if(event.target.id!=='accessService')return;const s=engine.getSession(),entry=s.profile.accessEntries?.find(v=>v.serviceId===event.target.value&&v.direction===s.intent.boundary);$('sourceInput').value=entry?.sources||'';$('portsInput').value=entry?.ports||'';$('businessForm').elements.complete.checked=!!entry?.complete;});
  $('businessForm').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.complete=!!data.complete;engine.act('preview-business',{part:$('businessPart').value,values:data});$('businessDialog').close();scrollOnRender=true;render();});
  $('deferForm').addEventListener('submit',e=>{e.preventDefault();engine.act('review',{kind:'暂缓',reason:$('deferReason').value});$('deferDialog').close();scrollOnRender=true;render();});
  window.mockAuditPrototype=engine;render();setInterval(()=>{const st=engine.getState();if(st.tasks.some(t=>['running','queued'].includes(t.status))){engine.tick();render();}},1150);
})();
